package probe;

import com.fluxtion.compiler.Fluxtion;
import com.fluxtion.compiler.builder.dataflow.DataFlow;
import com.fluxtion.runtime.EventProcessor;
import com.fluxtion.runtime.annotations.OnEventHandler;
import com.fluxtion.runtime.annotations.OnTrigger;
import com.fluxtion.runtime.dataflow.helpers.Aggregates;

public class Probe2 {

    public static class Counter {
        private int count;

        @OnEventHandler
        public boolean onString(String s) {
            count++;
            return true;
        }

        public int getCount() {
            return count;
        }
    }

    public static class Reporter {
        private final Counter counter;

        public Reporter(Counter counter) {
            this.counter = counter;
        }

        @OnTrigger
        public boolean report() {
            System.out.println("imperative count=" + counter.getCount());
            return true;
        }
    }

    public static void main(String[] args) {
        EventProcessor<?> processor = Fluxtion.interpret(c -> {
            c.addNode(new Reporter(new Counter()), "reporter");
            DataFlow.subscribe(String.class)
                    .map(String::length)
                    .aggregate(Aggregates.intSumFactory())
                    .console("dsl total length={}");
        });
        processor.init();
        processor.onEvent("hello");
        processor.onEvent("worlds!");
    }
}

