package com.example.riskwatch.node;

import com.example.riskwatch.event.MarketTick;
import com.fluxtion.runtime.annotations.OnEventHandler;

import java.util.HashMap;
import java.util.Map;

/**
 * Latest mid price per symbol.
 *
 * <p>The handler returns false when a tick repeats the price we already hold, which stops the rest
 * of the graph being recalculated for a no-op update.
 */
public class PriceBook {

    private final Map<String, Double> lastPrice = new HashMap<>();

    @OnEventHandler
    public boolean onTick(MarketTick tick) {
        Double previous = lastPrice.put(tick.symbol(), tick.price());
        return previous == null || previous != tick.price();
    }

    public double priceOf(String symbol) {
        return lastPrice.getOrDefault(symbol, Double.NaN);
    }

    public boolean hasPrice(String symbol) {
        return lastPrice.containsKey(symbol);
    }
}

package com.example.riskwatch.node;

import com.example.riskwatch.event.Trade;
import com.fluxtion.runtime.annotations.OnEventHandler;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

/**
 * Net position and average cost per symbol, built from the trade stream.
 *
 * <p>Average cost is only re-based while the position is growing in the same direction; reducing a
 * position leaves the cost basis alone, which is what a desk P&amp;L wants.
 */
public class PositionBook {

    private final Map<String, Integer> quantity = new LinkedHashMap<>();
    private final Map<String, Double> averageCost = new LinkedHashMap<>();
    private int tradeCount;

    @OnEventHandler
    public boolean onTrade(Trade trade) {
        String symbol = trade.symbol();
        int existingQty = quantity.getOrDefault(symbol, 0);
        double existingCost = averageCost.getOrDefault(symbol, 0.0);
        int newQty = existingQty + trade.quantity();

        if (existingQty == 0 || Integer.signum(existingQty) == Integer.signum(trade.quantity())) {
            // opening or adding: blend the cost basis
            double blended = (existingCost * existingQty + trade.price() * trade.quantity()) / newQty;
            averageCost.put(symbol, blended);
        } else if (Integer.signum(newQty) != Integer.signum(existingQty) && newQty != 0) {
            // flipped through zero: the new side starts at this trade price
            averageCost.put(symbol, trade.price());
        }

        quantity.put(symbol, newQty);
        tradeCount++;
        return true;
    }

    public Set<String> symbols() {
        return quantity.keySet();
    }

    public int quantityOf(String symbol) {
        return quantity.getOrDefault(symbol, 0);
    }

    public double averageCostOf(String symbol) {
        return averageCost.getOrDefault(symbol, 0.0);
    }

    public int getTradeCount() {
        return tradeCount;
    }
}

package com.example.riskwatch.node;

import com.example.riskwatch.event.RiskLimitUpdate;
import com.fluxtion.runtime.annotations.OnEventHandler;

import java.util.HashMap;
import java.util.Map;

/** Per symbol gross exposure limits, with a desk-wide default until the risk desk overrides one. */
public class LimitStore {

    private final double defaultLimit;
    private final Map<String, Double> limits = new HashMap<>();

    public LimitStore(double defaultLimit) {
        this.defaultLimit = defaultLimit;
    }

    @OnEventHandler
    public boolean onLimitUpdate(RiskLimitUpdate update) {
        limits.put(update.symbol(), update.maxExposure());
        return true;
    }

    public double limitFor(String symbol) {
        return limits.getOrDefault(symbol, defaultLimit);
    }
}

package com.example.riskwatch.node;

import com.fluxtion.runtime.annotations.OnTrigger;

import java.util.ArrayList;
import java.util.List;

/**
 * Marks the book against the latest prices.
 *
 * <p>Fluxtion works out that this node sits downstream of both books and calls {@link #revalue()}
 * once per event, after whichever parent changed has finished updating.
 */
public class MarkToMarket {

    /** One symbol's valuation at the current prices. */
    public record SymbolRisk(String symbol, int quantity, double averageCost, double price,
                             double exposure, double unrealisedPnl) {
    }

    private final PriceBook priceBook;
    private final PositionBook positionBook;
    private final List<SymbolRisk> risk = new ArrayList<>();
    private double totalPnl;
    private int revaluations;

    public MarkToMarket(PriceBook priceBook, PositionBook positionBook) {
        this.priceBook = priceBook;
        this.positionBook = positionBook;
    }

    @OnTrigger
    public boolean revalue() {
        risk.clear();
        totalPnl = 0;
        for (String symbol : positionBook.symbols()) {
            if (!priceBook.hasPrice(symbol)) {
                continue; // cannot mark a position we have no price for
            }
            int qty = positionBook.quantityOf(symbol);
            double cost = positionBook.averageCostOf(symbol);
            double price = priceBook.priceOf(symbol);
            double pnl = (price - cost) * qty;
            totalPnl += pnl;
            risk.add(new SymbolRisk(symbol, qty, cost, price, Math.abs(qty * price), pnl));
        }
        revaluations++;
        return !risk.isEmpty();
    }

    public List<SymbolRisk> getRisk() {
        return risk;
    }

    public double getTotalPnl() {
        return totalPnl;
    }

    public int getRevaluations() {
        return revaluations;
    }
}

package com.example.riskwatch.node;

import com.example.riskwatch.node.MarkToMarket.SymbolRisk;
import com.fluxtion.runtime.annotations.OnTrigger;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Compares marked exposure against the limits and raises an alert on each state change.
 *
 * <p>Triggered by either parent: a new valuation or a limit change can both move a symbol across
 * its limit, and neither call site has to know about the other.
 */
public class RiskMonitor {

    private final MarkToMarket markToMarket;
    private final LimitStore limitStore;
    private final Set<String> breached = new HashSet<>();
    private final List<String> alerts = new ArrayList<>();

    public RiskMonitor(MarkToMarket markToMarket, LimitStore limitStore) {
        this.markToMarket = markToMarket;
        this.limitStore = limitStore;
    }

    @OnTrigger
    public boolean checkLimits() {
        int alertsBefore = alerts.size();
        for (SymbolRisk symbolRisk : markToMarket.getRisk()) {
            String symbol = symbolRisk.symbol();
            double limit = limitStore.limitFor(symbol);
            boolean overLimit = symbolRisk.exposure() > limit;
            boolean wasOverLimit = breached.contains(symbol);
            if (overLimit && !wasOverLimit) {
                breached.add(symbol);
                alerts.add(String.format("BREACH  %-5s exposure %,.0f > limit %,.0f",
                        symbol, symbolRisk.exposure(), limit));
            } else if (!overLimit && wasOverLimit) {
                breached.remove(symbol);
                alerts.add(String.format("CLEARED %-5s exposure %,.0f <= limit %,.0f",
                        symbol, symbolRisk.exposure(), limit));
            }
        }
        for (int i = alertsBefore; i < alerts.size(); i++) {
            System.out.println("   !! " + alerts.get(i));
        }
        return alerts.size() > alertsBefore;
    }

    public List<String> getAlerts() {
        return alerts;
    }

    public Set<String> getBreachedSymbols() {
        return breached;
    }
}

package com.example.riskwatch.node;

import com.example.riskwatch.node.MarkToMarket.SymbolRisk;
import com.fluxtion.runtime.annotations.OnTrigger;

/**
 * Prints the marked book. Declared downstream of the monitor as well as the valuation so that any
 * alert for an event is printed above the table it belongs to.
 */
public class ConsoleReporter {

    private final MarkToMarket markToMarket;
    private final RiskMonitor riskMonitor;

    public ConsoleReporter(MarkToMarket markToMarket, RiskMonitor riskMonitor) {
        this.markToMarket = markToMarket;
        this.riskMonitor = riskMonitor;
    }

    @OnTrigger
    public boolean print() {
        StringBuilder sb = new StringBuilder();
        sb.append("   ┌───────┬────────┬───────────┬──────────┬──────────────┬──────────────┐\n");
        sb.append("   │ sym   │    qty │  avg cost │    price │     exposure │  unreal P&L  │\n");
        sb.append("   ├───────┼────────┼───────────┼──────────┼──────────────┼──────────────┤\n");
        for (SymbolRisk r : markToMarket.getRisk()) {
            sb.append(String.format("   │ %-5s │ %6d │ %9.2f │ %8.2f │ %,12.0f │ %,12.2f │%s%n",
                    r.symbol(), r.quantity(), r.averageCost(), r.price(), r.exposure(),
                    r.unrealisedPnl(),
                    riskMonitor.getBreachedSymbols().contains(r.symbol()) ? "  <-- OVER LIMIT" : ""));
        }
        sb.append("   └───────┴────────┴───────────┴──────────┴──────────────┴──────────────┘\n");
        sb.append(String.format("   total unrealised P&L: %,.2f%n", markToMarket.getTotalPnl()));
        System.out.print(sb);
        return true;
    }
}

package com.example.riskwatch;

import com.example.riskwatch.event.Trade;
import com.example.riskwatch.node.ConsoleReporter;
import com.example.riskwatch.node.LimitStore;
import com.example.riskwatch.node.MarkToMarket;
import com.example.riskwatch.node.PositionBook;
import com.example.riskwatch.node.PriceBook;
import com.example.riskwatch.node.RiskMonitor;
import com.fluxtion.compiler.Fluxtion;
import com.fluxtion.compiler.builder.dataflow.DataFlow;
import com.fluxtion.runtime.EventProcessor;
import com.fluxtion.runtime.dataflow.groupby.GroupBy;
import com.fluxtion.runtime.dataflow.helpers.Aggregates;

/**
 * Builds the RiskWatch event processor.
 *
 * <p>Nothing here says what order anything runs in. The only thing declared is which node needs
 * which other node; Fluxtion derives the dispatch order from those references.
 */
public final class RiskWatchGraph {

    public static final double DEFAULT_LIMIT = 250_000;

    private RiskWatchGraph() {
    }

    /** The processor plus the node instances, so a caller (or a test) can read final state. */
    public record RiskWatch(EventProcessor<?> processor,
                            PositionBook positionBook,
                            MarkToMarket markToMarket,
                            RiskMonitor riskMonitor) {

        public void onEvent(Object event) {
            processor.onEvent(event);
        }
    }

    public static RiskWatch build(double defaultLimit) {
        PriceBook priceBook = new PriceBook();
        PositionBook positionBook = new PositionBook();
        LimitStore limitStore = new LimitStore(defaultLimit);
        MarkToMarket markToMarket = new MarkToMarket(priceBook, positionBook);
        RiskMonitor riskMonitor = new RiskMonitor(markToMarket, limitStore);
        ConsoleReporter reporter = new ConsoleReporter(markToMarket, riskMonitor);

        EventProcessor<?> processor = Fluxtion.interpret(config -> {
            // imperative half: the risk book. Adding the leaf pulls in everything it references.
            config.addNode(reporter, "consoleReporter");

            // functional half: running traded notional per trader, off the same Trade stream
            DataFlow.subscribe(Trade.class)
                    .groupBy(Trade::trader, Trade::notional, Aggregates.doubleSumFactory())
                    .map(GroupBy::toMap)
                    .console("   traded notional by trader: {}");
        });
        processor.init();
        return new RiskWatch(processor, positionBook, markToMarket, riskMonitor);
    }

    public static RiskWatch build() {
        return build(DEFAULT_LIMIT);
    }
}

package com.example.riskwatch;

import com.example.riskwatch.event.MarketTick;
import com.example.riskwatch.event.RiskLimitUpdate;
import com.example.riskwatch.event.Trade;

import java.util.List;

/**
 * A fixed morning of events. Scripted rather than random so the printed output can be checked by
 * hand and replayed to the same result — see {@code RiskWatchTest}.
 */
public final class EventFeed {

    private EventFeed() {
    }

    public static List<Object> scriptedSession() {
        return List.of(
                new MarketTick("ACME", 100.00),
                new Trade("alice", "ACME", 1000, 100.00),
                new MarketTick("ACME", 102.50),
                new MarketTick("BETA", 50.00),
                new Trade("bob", "BETA", -2000, 50.00),
                // takes ACME exposure to 256,250 against the 250,000 default limit
                new Trade("alice", "ACME", 1500, 103.00),
                new MarketTick("BETA", 47.50),
                // risk desk raises the ACME limit, which clears the breach with no new trade
                new RiskLimitUpdate("ACME", 400_000),
                // same price as the last ACME tick: PriceBook stops it, nothing downstream runs
                new MarketTick("ACME", 102.50),
                new Trade("bob", "ACME", -500, 101.00),
                new MarketTick("ACME", 110.00),
                // BETA short grows to 6,000 and breaches
                new Trade("carol", "BETA", -4000, 47.50),
                // BETA sells off, exposure drops back under the limit
                new MarketTick("BETA", 40.00));
    }

    public static String describe(Object event) {
        if (event instanceof MarketTick t) {
            return String.format("TICK   %-5s %8.2f", t.symbol(), t.price());
        }
        if (event instanceof Trade t) {
            return String.format("TRADE  %-5s %+6d @ %8.2f  (%s)", t.symbol(), t.quantity(),
                    t.price(), t.trader());
        }
        if (event instanceof RiskLimitUpdate t) {
            return String.format("LIMIT  %-5s max exposure %,.0f", t.symbol(), t.maxExposure());
        }
        return event.toString();
    }
}

package com.example.riskwatch;

import com.example.riskwatch.RiskWatchGraph.RiskWatch;

import java.util.List;

/** Feeds the scripted session through the graph, one event at a time. */
public class RiskWatchMain {

    public static void main(String[] args) {
        System.out.printf("RiskWatch — default gross exposure limit %,.0f%n%n",
                RiskWatchGraph.DEFAULT_LIMIT);

        RiskWatch riskWatch = RiskWatchGraph.build();
        List<Object> session = EventFeed.scriptedSession();

        for (int i = 0; i < session.size(); i++) {
            Object event = session.get(i);
            System.out.printf("%n[%02d] %s%n", i + 1, EventFeed.describe(event));
            riskWatch.onEvent(event);
        }

        System.out.printf("%n%s%n", "-".repeat(72));
        System.out.printf("events fed        : %d%n", session.size());
        System.out.printf("trades booked     : %d%n", riskWatch.positionBook().getTradeCount());
        System.out.printf("book revaluations : %d%n", riskWatch.markToMarket().getRevaluations());
        System.out.printf("total unreal P&L  : %,.2f%n", riskWatch.markToMarket().getTotalPnl());
        System.out.println("risk alerts       :");
        riskWatch.riskMonitor().getAlerts().forEach(a -> System.out.println("    " + a));
    }
}

package com.example.riskwatch;

import com.example.riskwatch.RiskWatchGraph.RiskWatch;
import com.example.riskwatch.event.MarketTick;
import com.example.riskwatch.node.MarkToMarket.SymbolRisk;
import org.junit.jupiter.api.Test;

import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class RiskWatchTest {

    private static RiskWatch runScriptedSession() {
        RiskWatch riskWatch = RiskWatchGraph.build();
        EventFeed.scriptedSession().forEach(riskWatch::onEvent);
        return riskWatch;
    }

    @Test
    void booksPositionsAndCostBasis() {
        RiskWatch riskWatch = runScriptedSession();

        assertEquals(5, riskWatch.positionBook().getTradeCount());
        assertEquals(2000, riskWatch.positionBook().quantityOf("ACME"));
        assertEquals(-6000, riskWatch.positionBook().quantityOf("BETA"));
        // (100.00 * 1000 + 103.00 * 1500) / 2500, untouched by the later sell
        assertEquals(101.80, riskWatch.positionBook().averageCostOf("ACME"), 1e-9);
        assertEquals(290_000d / 6000, riskWatch.positionBook().averageCostOf("BETA"), 1e-9);
    }

    @Test
    void marksTheBookAgainstLatestPrices() {
        RiskWatch riskWatch = runScriptedSession();
        List<SymbolRisk> risk = riskWatch.markToMarket().getRisk();

        assertEquals(2, risk.size());
        assertEquals(16_400, risk.get(0).unrealisedPnl(), 1e-9);   // (110.00 - 101.80) * 2000
        assertEquals(50_000, risk.get(1).unrealisedPnl(), 1e-9);   // (40.00 - 48.333..) * -6000
        assertEquals(66_400, riskWatch.markToMarket().getTotalPnl(), 1e-9);
    }

    @Test
    void raisesAnAlertOnEachLimitCrossing() {
        RiskWatch riskWatch = runScriptedSession();

        assertEquals(List.of(
                        "BREACH  ACME  exposure 256,250 > limit 250,000",
                        "CLEARED ACME  exposure 256,250 <= limit 400,000",
                        "BREACH  BETA  exposure 285,000 > limit 250,000",
                        "CLEARED BETA  exposure 240,000 <= limit 250,000"),
                riskWatch.riskMonitor().getAlerts());
        assertTrue(riskWatch.riskMonitor().getBreachedSymbols().isEmpty());
    }

    @Test
    void repeatedPriceDoesNotRevalueTheBook() {
        RiskWatch riskWatch = RiskWatchGraph.build();
        EventFeed.scriptedSession().forEach(riskWatch::onEvent);

        int revaluations = riskWatch.markToMarket().getRevaluations();
        riskWatch.onEvent(new MarketTick("BETA", 40.00)); // same price as the last tick
        assertEquals(revaluations, riskWatch.markToMarket().getRevaluations());

        riskWatch.onEvent(new MarketTick("BETA", 41.00));
        assertEquals(revaluations + 1, riskWatch.markToMarket().getRevaluations());
    }

    @Test
    void replayingTheSameFeedGivesTheSameResult() {
        RiskWatch first = runScriptedSession();
        RiskWatch second = runScriptedSession();

        assertEquals(first.riskMonitor().getAlerts(), second.riskMonitor().getAlerts());
        assertEquals(first.markToMarket().getTotalPnl(), second.markToMarket().getTotalPnl());
        assertEquals(first.markToMarket().getRevaluations(),
                second.markToMarket().getRevaluations());
    }
}
